<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import {operationMessage,type LocalLauncherClient} from './local-api';import type {GameInstance} from './local-types';import {resourceInfo,type ResourceKind,type ResourceListing,type ResourceEntry} from './resource-types';import {currentEntryContext} from './entry';import './resource-manager.css';
const props=defineProps<{client:LocalLauncherClient;instances:GameInstance[];kind:ResourceKind;instancesLoading?:boolean;instancesError?:string}>();
const instanceId=ref(''),listing=ref<ResourceListing|null>(null),busy=ref(false),error=ref(''),notice=ref(''),source=ref(''),query=ref('');const info=computed(()=>resourceInfo[props.kind]);const action=ref<{entry:ResourceEntry;operation:'COPY'|'RENAME'|'REMOVE'}|null>(null),target=ref('');
let controller=new AbortController(),sequence=0,alive=true,unlisten:(()=>void)|undefined;
const entries=computed(()=>listing.value?.entries.filter(e=>e.name.toLocaleLowerCase().includes(query.value.toLocaleLowerCase()))??[]);
watch(()=>props.instances,values=>{if(!values.some(i=>i.id===instanceId.value))instanceId.value=values[0]?.id??'';},{immediate:true});
async function load(){controller.abort();controller=new AbortController();const current=++sequence;listing.value=null;action.value=null;error.value='';notice.value='';source.value='';if(!instanceId.value){busy.value=false;return;}busy.value=true;try{const value=await props.client.resources(instanceId.value,props.kind,controller.signal);if(alive&&current===sequence)listing.value=value;}catch(e){if(alive&&current===sequence)error.value=operationMessage(e);}finally{if(current===sequence)busy.value=false;}}
watch([instanceId,()=>props.kind],()=>void load(),{immediate:true});
async function mutate(work:()=>Promise<ResourceListing>,message:string){if(busy.value||!listing.value)return;busy.value=true;error.value='';notice.value='';const current=sequence;try{const value=await work();if(alive&&current===sequence){listing.value=value;action.value=null;source.value='';notice.value=message;}}catch(e){if(alive&&current===sequence)error.value=operationMessage(e)+'；若操作已提交，请刷新核对结果。';}finally{if(current===sequence)busy.value=false;}}
function importing(){if(!source.value.trim())return;void mutate(()=>props.client.importResource(instanceId.value,props.kind,source.value.trim(),controller.signal),'文件已复制到本实例；源文件未修改，请按说明在游戏内使用。');}
function chooseAction(entry:ResourceEntry,operation:'COPY'|'RENAME'|'REMOVE'){action.value={entry,operation};const dot=entry.name.lastIndexOf('.');target.value=operation==='COPY'?entry.name.slice(0,dot)+'-副本'+entry.name.slice(dot):entry.name;}
function confirm(){const value=action.value;if(!value)return;void mutate(()=>props.client.changeResource(instanceId.value,props.kind,value.entry,value.operation,value.operation==='REMOVE'?null:target.value,controller.signal),'操作完成；改名与移除的原件备份保留在本实例。');}
async function choose(){const request=sequence;if(!currentEntryContext().native){error.value='文件选择需要独立EXE；也可填写本机源文件路径。';return;}try{const {invoke}=await import('@tauri-apps/api/core');const selected=await invoke<string|null>('launcher_choose_resource',{kind:props.kind});if(alive&&request===sequence&&selected)source.value=selected;}catch(e){if(alive)error.value=operationMessage(e);}}
async function openDirectory(){if(!listing.value)return;try{const {invoke}=await import('@tauri-apps/api/core');await invoke('launcher_open_resource_directory',{instanceId:instanceId.value,kind:props.kind});}catch(e){error.value=operationMessage(e);}}
function bytes(value:number){return value<1048576?(value/1024).toFixed(1)+' KiB':(value/1048576).toFixed(1)+' MiB';}
onMounted(async()=>{if(!currentEntryContext().native)return;try{const {getCurrentWebview}=await import('@tauri-apps/api/webview');const stop=await getCurrentWebview().onDragDropEvent(event=>{if(alive&&event.payload.type==='drop'&&!busy.value){if(event.payload.paths.length===1)source.value=event.payload.paths[0]??'';else error.value='每次请选择一个资源文件。';}});if(alive)unlisten=stop;else stop();}catch{/* 路径输入仍可使用。 */}});
onBeforeUnmount(()=>{alive=false;++sequence;controller.abort();unlisten?.();});
</script>
<template><section class="launcher-local-page resource-manager" :data-resource-kind="kind"><div class="launcher-section-heading"><div><span class="launcher-overline">YOUR RESOURCES</span><h1>{{info.title}}</h1><p>{{info.help}}</p></div></div>
<p v-if="instancesError" class="launcher-inline-notice" role="alert">{{instancesError}}</p><p v-if="error" class="launcher-inline-notice" role="alert">{{error}}</p><p v-if="notice" class="launcher-inline-notice" role="status">{{notice}}</p>
<p v-if="instancesLoading" role="status">正在读取实例…</p><p v-else-if="!instances.length&&!instancesError">先准备一个实例，再管理此类资源。</p>
<template v-if="instances.length"><div class="resource-toolbar"><label>游戏实例<select data-resource-instance v-model="instanceId" :disabled="busy"><option v-for="instance in instances" :key="instance.id" :value="instance.id">{{instance.name}} · {{instance.gameVersion}}</option></select></label><button class="launcher-secondary" data-resource-refresh :disabled="busy" @click="load">刷新列表</button><button class="launcher-text-link" :disabled="!listing||busy" @click="openDirectory">打开资源文件夹 ↗</button></div>
<p v-if="busy" role="status">正在处理本实例资源…</p><template v-if="listing"><form class="resource-import launcher-glass" @submit.prevent="importing"><strong>添加到本实例</strong><p>选择或拖入一个文件；最多512MiB，不覆盖同名、不自动启用。</p><div><input data-resource-source v-model="source" aria-label="资源源文件路径" placeholder="选择文件、拖入文件，或填写完整路径" :disabled="busy"/><button class="launcher-secondary" type="button" data-resource-choose :disabled="busy" @click="choose">选择文件</button><button class="launcher-primary" data-resource-import :disabled="busy||!source.trim()">导入资源</button></div></form>
<div v-if="action" class="resource-confirm launcher-glass" aria-label="确认资源操作" @keydown.esc="action=null"><h2>{{action.operation==='REMOVE'?'备份并移除':action.operation==='COPY'?'复制独立副本':'改名并备份'}}</h2><p>{{action.entry.name}}</p><input v-if="action.operation!=='REMOVE'" data-resource-target v-model="target" aria-label="新文件名称" maxlength="128" :disabled="busy"/><p>仅影响当前实例；原文件或备份保留。游戏运行中不能修改。</p><button class="launcher-secondary" data-resource-confirm :disabled="busy||action.operation!=='REMOVE'&&!target.trim()" @click="confirm">确认{{action.operation==='REMOVE'?'备份移除':'操作'}}</button><button :disabled="busy" @click="action=null">取消</button></div>
<label class="resource-filter">筛选文件<input data-resource-query v-model="query" placeholder="按名称查找"/></label><div class="resource-file-list"><article v-for="entry in entries" :key="entry.name" :data-resource-file="entry.name" class="launcher-glass resource-file"><div><strong>{{entry.name}}</strong><small>{{bytes(entry.size)}} · {{new Date(entry.modifiedAt).toLocaleString()}}</small></div><div class="resource-file-actions"><button class="launcher-secondary" :data-resource-copy="entry.name" :disabled="busy" @click="chooseAction(entry,'COPY')">复制副本</button><button :data-resource-rename="entry.name" :disabled="busy" @click="chooseAction(entry,'RENAME')">改名</button><button :data-resource-remove="entry.name" :disabled="busy" @click="chooseAction(entry,'REMOVE')">备份移除</button></div></article></div><p v-if="!entries.length&&!error">{{query?'没有匹配的文件':'还没有此类资源，可以选择文件导入。'}}</p>
<details class="resource-backups"><summary>移除与改名备份 · {{listing.backups.length}}</summary><article v-for="backup in listing.backups" :key="backup.id" class="resource-file launcher-glass"><div><strong>{{backup.name}}</strong><small>{{new Date(backup.createdAt).toLocaleString()}} · {{bytes(backup.size)}}</small></div><button class="launcher-secondary" :data-resource-restore="backup.id" :disabled="busy" @click="mutate(()=>client.restoreResource(instanceId,kind,backup.id,controller.signal),'备份已恢复；现有同名文件不会覆盖。')">恢复原名</button></article><p>备份保留；恢复不会覆盖现有同名文件。</p></details>
<p v-for="problem in listing.problems" :key="problem.name" class="launcher-inline-notice">{{problem.name}} · {{problem.message}}</p><p class="launcher-caption resource-directory">{{listing.directory}}</p></template></template></section></template>
